  "settings.rockstar.scanBtn": "Analyser les jeux installés",
  "settings.ubisoft.desc": "Importez votre bibliothèque Ubisoft Connect — jeux installés et catalogue complet — et lancez des titres via le client Ubisoft Connect. Aucun compte requis.",
